          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '1rem',
          marginBottom: '1.5rem',
        }}
      >
        <div>
          <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
          <p
            style={{
              margin: '0.25rem 0 0',
              color: '#6b7280',
              fontSize: '0.875rem',
            }}
          >
            {products.length} SKUs · cached with tag{' '}
            <code>&quot;{PRODUCTS_CACHE_TAG}&quot;</code>
          </p>
        </div>

        <form action={syncLatestCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 0.9rem',
              border: '1px solid #111827',
              background: '#111827',
              color: '#fff',
              borderRadius: 6,
              cursor: 'pointer',
              fontSize: '0.875rem',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          fontSize: '0.9rem',
        }}
      >
        <thead>
          <tr style={{ textAlign: 'left', borderBottom: '1px solid #e5e7eb' }}>
            <th style={{ padding: '0.5rem 0.75rem' }}>ID</th>
            <th style={{ padding: '0.5rem 0.75rem' }}>Name</th>
            <th
              style={{
                padding: '0.5rem 0.75rem',
                textAlign: 'right',
              }}
            >
              Price
            </th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => (
            <tr key={p.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
              <td style={{ padding: '0.5rem 0.75rem', color: '#6b7280' }}>
                {p.id}
              </td>
              <td style={{ padding: '0.5rem 0.75rem' }}>{p.name}</td>
              <td
                style={{
                  padding: '0.5rem 0.75rem',
                  textAlign: 'right',
                  fontVariantNumeric: 'tabular-nums',
                }}
              >
                ${p.price}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}
